namespace VinsPDF {
internal static class Version029Tests {
 internal static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return Convert.ToBase64String(h.ComputeHash(s));}
 static bool EqualPixels(Bitmap a,Bitmap b){if(a.Size!=b.Size)return false;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))return false;return true;}
 public static int Run(string[] args){string dir=args[1];Directory.CreateDirectory(dir);try{using(var e=new PdfEngine()){e.Open(args[2]);Assert(e.PageLabels().SequenceEqual(new[]{"i","ii","1","2"}),"Page labels missing");var insensitive=e.SearchPage(0,"welding",false);var sensitive=e.SearchPage(0,"WELDING",true);Assert(insensitive.Count>sensitive.Count&&sensitive.Count==1,"Search case handling failed");Assert(insensitive.All(h=>h.Boxes.Length>0&&h.Boxes.All(b=>b.Width>0&&b.Height>0&&b.X>=0&&b.Y>=0)),"Search rectangles wrong");var hit=e.SearchPage(0,"continuity",false).First();var before=e.Preview(0,0,1000);e.HighlightText(0,hit.Start,hit.Count,Color.Yellow);using(var b=e.Preview(0,0,1000)){b.Save(Path.Combine(dir,"highlight.png"));Assert(!EqualPixels(before,b),"Highlight did not render");}e.UndoEdit(false);using(var b=e.Preview(0,0,1000))Assert(EqualPixels(before,b),"Highlight undo changed page appearance");e.UndoEdit(true);e.SaveCopy(Path.Combine(dir,"highlight-saved.pdf"));using(var b=e.Preview(0,0,1000)){b.Save(Path.Combine(dir,"highlight-reopened.png"));Assert(!EqualPixels(before,b),"Saved highlight disappeared");}before.Dispose();
 var paragraphs=TextParagraphs.Group(TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true),e.Sizes[0],true);var paragraph=paragraphs.First(o=>o.IsParagraph&&o.Text.StartsWith("The stability"));Assert(paragraph.Text.Contains("\n\nWhere the"),"Adjacent paragraphs or their break were lost");Assert(!paragraph.Text.Contains("Front cover")&&!paragraph.Text.Contains("Search target"),"Text block crossed unrelated sections");float height=paragraph.Bounds.Height;string replacement=paragraph.Text.Insert(40," Additional wording must reflow the lines in this paragraph as the text becomes longer. Additional wording must reflow the lines in this paragraph as the text becomes longer. ");e.PutTextBlock(0,paragraph.Ids,replacement,paragraph.Style.Copy(),new PointF(paragraph.BaselineX,paragraph.BaselineY));var edited=TextParagraphs.Group(TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true),e.Sizes[0],true).First(o=>o.BlockKey==paragraph.BlockKey);Assert(edited.IsParagraph&&edited.Bounds.Height>height&&edited.Text.Contains("Additional wording"),"Paragraph did not reflow");e.RotateObjects(0,edited.Ids,edited.Bounds,90);var rotated=TextParagraphs.Group(TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true),e.Sizes[0],true).First(o=>o.BlockKey==edited.BlockKey);Assert(rotated.Text==edited.Text,"Rotating a text block changed reading order");e.UndoEdit(false);e.SaveCopy(Path.Combine(dir,"paragraph-saved.pdf"));Assert(TextParagraphs.Group(TextLines.Group(e.GetObjects(0).Objects,e.Sizes[0],true),e.Sizes[0],true).Any(o=>o.IsParagraph&&o.Text.Contains("Additional wording")),"Saved paragraph grouping lost");using(var b=e.Preview(0,0,1000))b.Save(Path.Combine(dir,"paragraph.png"));
 e.ExportCopy(Path.Combine(dir,"uncompressed.pdf"));int textCount=e.SearchPage(0,"welding",false).Count;e.ExportEditableReduced(Path.Combine(dir,"editable-fast.pdf"),Enumerable.Range(0,4).ToArray(),80);e.ExportEditableReduced(Path.Combine(dir,"editable-reduced.pdf"),Enumerable.Range(0,4).ToArray(),80,true);using(var c=new PdfEngine()){c.Open(Path.Combine(dir,"editable-reduced.pdf"));Assert(c.Count==4&&c.SearchPage(0,"welding",false).Count==textCount&&c.GetObjects(0).Objects.Any(o=>o.Kind==1),"Editable export flattened/lost text");}Assert(new FileInfo(Path.Combine(dir,"editable-reduced.pdf")).Length<new FileInfo(Path.Combine(dir,"uncompressed.pdf")).Length*.99,"Compression did not reduce fixture");
 e.ExportOrganised(Path.Combine(dir,"organised.pdf"),new[]{2,0,3,1},new[]{1,0,0,0});using(var c=new PdfEngine()){c.Open(Path.Combine(dir,"organised.pdf"));Assert(c.PageLabels().SequenceEqual(new[]{"1","i","2","ii"}),"Organise lost page labels");Assert(c.Sizes[0].Width>c.Sizes[0].Height,"Organise rotation wrong");}
 string original=Path.Combine(dir,"later-original.pdf");File.Copy(args[2],original,true);e.Open(original);string hash=Hash(original);e.OrganiseInMemory(new[]{3,0,1},new[]{0,0,1});Assert(Hash(original)==hash&&e.Count==3&&e.PageLabels().SequenceEqual(new[]{"2","i","ii"}),"Save later touched source or wrong pages");e.SaveCopy(original);Assert(Hash(original)!=hash&&e.Count==3,"Save later did not persist on save");}
 File.WriteAllText(Path.Combine(dir,"engine-029.txt"),"PASS search/case/rectangles, page labels, highlight render/undo/redo/save, paragraph grouping/reflow/persistence, editable compression, organised labels/order/rotation, deferred original-file save.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"engine-029.txt"),"FAIL "+ex);return 1;}}
}
internal sealed partial class MainForm {
