 void Start029Test(){int stage=0,ticks=0;bool processing=false;var timer=new Timer{Interval=150};Rectangle camera=Rectangle.Empty;Stopwatch undoClock=new Stopwatch();timer.Tick+=delegate{if(processing)return;if(++ticks>2200){Trace("FAIL 029 timeout stage "+stage);timer.Stop();dirty=false;CancelInline();WindowSession.Current.CloseAll();return;}if(editBusy||lastRenderedVersion!=viewVersion)return;processing=true;try{switch(stage++){
 case 0:var shell=TopLevelControl as TabWindow;var bounds=shell.Bounds;shell.ToggleFullScreen();Version029Tests.Assert(shell.Bounds==Screen.FromControl(shell).Bounds,"F11 not fullscreen");shell.ToggleFullScreen();Version029Tests.Assert(shell.Bounds==bounds,"Fullscreen restore changed bounds");canvas.Fit("page");canvas.ScrollWheel(-120);Version029Tests.Assert(pageIndex==1,"Wheel did not turn exactly one page");canvas.ScrollWheel(-120);Version029Tests.Assert(pageIndex==2,"Second wheel notch failed");Navigate(0);break;
 case 1:pageBox.Text=pageLabels.Contains("1")?"1":"#1";JumpToLabel();Version029Tests.Assert(pageIndex==Array.IndexOf(pageLabels,"1"),"Label navigation failed");ShowSearch();searchInput.Text=sizes.Length==4?"welding":"FRAME";searchDelay.Stop();StartSearch();break;
 case 2:if(searchHits.Count<2){stage--;break;}Version029Tests.Assert(canvas.SearchBoxes.Length>0,"Search overlay missing");NextSearch(1);Version028Tests.Capture(TopLevelControl,Path.Combine(V029Directory,"search.png"));HideSearch();Navigate(0);ToggleMark();break;
 case 3:if(canvas.MarkGlyphs.Count==0){stage--;break;}var glyph=canvas.MarkGlyphs.First();Point point=new Point(canvas.PageRectangle.X+(int)((glyph.Bounds.Left+glyph.Bounds.Width/2)*canvas.PageRectangle.Width),canvas.PageRectangle.Y+(int)((glyph.Bounds.Top+glyph.Bounds.Height/2)*canvas.PageRectangle.Height));canvas.TestDrag(point,new Point(point.X+50,point.Y));break;
 case 4:Version029Tests.Assert(dirty&&editorState.CanUndo,"Highlight not recorded");ToggleMark();ToggleEditing();break;
 case 5:if(canvas.Objects.Count==0){stage--;break;}Version029Tests.Assert(Math.Abs(palette.Opacity-.9)<.001&&!palette.MoveButton.Visible,"Palette modes/opacity wrong");if(sizes.Length==4){var paragraph=canvas.Objects.First(o=>o.IsParagraph&&o.Text.StartsWith("The stability"));BeginInline(paragraph);inlineText.Text=inlineText.Text.Insert(35," Expanded paragraph content for this editing test. ");}else{BeginInline(null);inlineText.Text="VinsPDF 0.29 undo timing";}Version028Tests.Capture(palette,Path.Combine(V029Directory,"palette.png"));Version028Tests.Capture(TopLevelControl,Path.Combine(V029Directory,"paragraph-edit.png"));Version029Tests.Assert(palette.Style.Wrap,"Font panel lost paragraph wrapping");PaletteCommand("fontapply");break;
 case 6:camera=canvas.PageRectangle;undoClock.Restart();UndoEditor(false);Trace("undo_immediate_frame_ms="+undoClock.ElapsedMilliseconds);break;
 case 7:undoClock.Stop();Trace("undo_ui_completion_ms="+undoClock.ElapsedMilliseconds);Version029Tests.Assert(camera==canvas.PageRectangle,"Undo moved camera");UndoEditor(true);break;
 case 8:ShowOverview();break;
 case 9:Version029Tests.Assert(overview!=null&&overview.Width<=438&&overview.Left>=expandPages.PointToScreen(Point.Empty).X,"Overview size/position wrong");Version028Tests.Capture(overview,Path.Combine(V029Directory,"overview.png"));overview.Close();using(var about=new AboutVinsPDF()){about.Show(TopLevelControl);Version028Tests.Capture(about,Path.Combine(V029Directory,"about.png"));about.Close();}using(var extract=new ExtractDialog(0,sizes.Length)){extract.Show(TopLevelControl);Version028Tests.Capture(extract,Path.Combine(V029Directory,"extract.png"));extract.Close();}using(var export=new ExportOptions(sizes.Length,0)){export.Show(TopLevelControl);Version028Tests.Capture(export,Path.Combine(V029Directory,"export.png"));export.Close();}if(sizes.Length==4){currentPath=Path.Combine(V029Directory,"ui-original.pdf");Version029Tests.Assert(SaveBeforeClose(currentPath),"Test copy save failed");ApplyOrganisedPages(new[]{new PageChoice{Index=2,Rotation=1},new PageChoice{Index=0},new PageChoice{Index=1},new PageChoice{Index=3}});}else Version029Tests.Assert(SaveBeforeClose(Path.Combine(V029Directory,"large-edited.pdf")),"Large PDF save failed");break;
 case 10:if(sizes.Length==4){Version029Tests.Assert(structurePending&&dirty&&pageLabels[0]=="1","Deferred organise not applied");using(var answer=new Timer{Interval=100}){answer.Tick+=delegate{foreach(Form f in Application.OpenForms)if(f is SaveChangesDialog){answer.Stop();Version028Tests.Capture(f,Path.Combine(V029Directory,"save-original.png"));f.DialogResult=DialogResult.Yes;break;}};answer.Start();Version029Tests.Assert(ConfirmDiscard(),"Original save cancelled");}Version029Tests.Assert(!dirty,"Original save remains dirty");}Trace("PASS 029 search/highlight, labels, wheel steps, F11, paragraph editor, quick undo/redo, compact overview, About/extract/export, deferred save");timer.Stop();dirty=false;((TabWindow)TopLevelControl).TestTabs029(V029Directory);WindowSession.Current.CloseAll();break;
 }}catch(Exception ex){Trace("FAIL 029 stage="+(stage-1)+" "+ex);timer.Stop();CancelInline();dirty=false;WindowSession.Current.CloseAll();}finally{processing=false;}};timer.Start();}
}
